syntax:
CREATE FUNCTION nome(parametros) RETURNS tipo AS $$
BEGIN
  -- lógica
  RETURN valor;
END;
$$ LANGUAGE plpgsql;

example:
CREATE FUNCTION calcular_desconto(preco NUMERIC, percentual NUMERIC)
RETURNS NUMERIC AS $$
BEGIN
  RETURN preco - (preco * percentual / 100);
END;
$$ LANGUAGE plpgsql;

